import torch
import torch.nn as nn
from torch.autograd import Function
from torch.utils.cpp_extension import load_inline

add_bias_clamp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void add_bias_clamp_kernel(
    const float* input,
    const float* bias,
    float max_val,
    float* output,
    int num_elements,
    int C,
    int H,
    int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int channel = (idx / (H * W)) % C;
    float val = input[idx] + bias[channel];
    val = fmaxf(0.0f, fminf(val, max_val));
    output[idx] = val;
}

torch::Tensor add_bias_clamp_cuda(
    torch::Tensor input,
    torch::Tensor bias,
    float max_val
) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    add_bias_clamp_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        max_val,
        output.data_ptr<float>(),
        num_elements,
        C,
        H,
        W
    );

    return output;
}
"""

add_bias_clamp_cpp = "torch::Tensor add_bias_clamp_cuda(torch::Tensor input, torch::Tensor bias, float max_val);"

add_bias_clamp = load_inline(
    name='add_bias_clamp',
    cpp_sources=add_bias_clamp_cpp,
    cuda_sources=add_bias_clamp_source,
    functions=['add_bias_clamp_cuda'],
    verbose=True
)

class AddBiasClamp(Function):
    @staticmethod
    def forward(ctx, input, bias, max_val):
        ctx.save_for_backward(input, bias)
        ctx.max_val = max_val
        return add_bias_clamp.add_bias_clamp_cuda(input, bias, max_val)

    @staticmethod
    def backward(ctx, grad_output):
        input, bias = ctx.saved_tensors
        max_val = ctx.max_val

        x_plus_b = input + bias.view(1, -1, 1, 1)
        mask = (x_plus_b > 0) & (x_plus_b < max_val)
        grad_input = grad_output * mask.float()
        grad_bias = grad_input.sum(dim=(0, 2, 3)).view_as(bias)

        return grad_input, grad_bias, None

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape, scaling_factor):
        super().__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, 
                                               stride=stride, padding=padding, 
                                               output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = self.conv_transpose(x)
        x = AddBiasClamp.apply(x, self.bias.squeeze(), 1.0/self.scaling_factor)
        return x
